/**
 * @import {BaseParquetReadOptions, FileMetaData, RowGroup} from '../src/types.js'
 */

import { columnsNeededForFilter } from './filter.js'
import { parquetMetadataAsync } from './metadata.js'
import { parquetReadObjects } from './read.js'
import { clampRowRange, rowGroupSlices, rowGroupSpans } from './utils.js'

/**
 * Validates the read options and resolves the row range to count.
 * Returns undefined when the range holds no rows.
 *
 * @param {BaseParquetReadOptions} options
 * @returns {Promise<{ metadata: FileMetaData, start: number, end: number } | undefined>}
 */
async function resolveRange(options) {
  if (!options.file || !(options.file.byteLength >= 0)) {
    throw new Error('parquet expected AsyncBuffer')
  }
  options.metadata ??= await parquetMetadataAsync(options.file, options)

  const { metadata, rowStart = 0 } = options
  if (rowStart < 0) throw new Error('parquet rowStart must be positive')
  const range = clampRowRange(rowStart, options.rowEnd, Number(metadata.num_rows))
  if (!range) return undefined
  return { metadata, start: range[0], end: range[1] }
}

/**
 * Counts the rows in a row range, optionally only the rows that match a filter.
 * Without a filter the count comes from the metadata and no data is read.
 * With a filter, rowStart and rowEnd bound the physical rows that are tested.
 * The filter columns are read one row group at a time.
 *
 * @param {BaseParquetReadOptions} options
 * @returns {Promise<number>} the number of rows in the range that match
 */
export async function parquetCount(options) {
  const resolved = await resolveRange(options)
  if (!resolved) return 0
  const { metadata, start, end } = resolved
  if (!options.filter) return end - start

  const columns = columnsNeededForFilter(options.filter)
  let count = 0
  for (const [sliceStart, sliceEnd] of rowGroupSlices(metadata, start, end)) {
    const rows = await parquetReadObjects({ ...options, columns, rowStart: sliceStart, rowEnd: sliceEnd })
    count += rows.length
  }
  return count
}

/**
 * Counts the rows of a row range where a top-level column has no value.
 * A row group that lies wholly inside the range is counted from its column
 * statistics when they report a null count. Every other part of the range is
 * read. A filter in the options is ignored.
 *
 * @param {Omit<BaseParquetReadOptions, 'filter'> & { column: string }} options
 * @returns {Promise<number>} the number of rows in the range where the column is missing
 */
export async function parquetCountNulls(options) {
  const { column } = options
  if (typeof column !== 'string') throw new Error('parquet column expected')
  const resolved = await resolveRange(options)
  if (!resolved) return 0
  const { metadata, start, end } = resolved

  let nulls = 0
  for (const span of rowGroupSpans(metadata, start, end)) {
    if (span.end <= span.start) continue
    const known = span.whole ? statisticsNullCount(metadata.row_groups[span.group], column) : undefined
    if (known !== undefined) {
      nulls += known
      continue
    }
    const found = await parquetReadObjects({
      ...options, filter: undefined, columns: [column], rowStart: span.start, rowEnd: span.end,
    })
    for (const row of found) {
      if (row[column] === null || row[column] === undefined) nulls++
    }
  }
  return nulls
}

/**
 * Reads the null count that the statistics of a row group report for a column.
 * A statistics null count tallies leaf values, so it equals the number of
 * missing rows only for a column that is a single leaf.
 *
 * @param {RowGroup} group
 * @param {string} column top-level column name
 * @returns {number | undefined} undefined when the statistics give no usable count
 */
function statisticsNullCount(group, column) {
  const chunk = group.columns.find(c => c.meta_data?.path_in_schema.length === 1 && c.meta_data.path_in_schema[0] === column)
  const nullCount = chunk?.meta_data?.statistics?.null_count
  return nullCount === undefined ? undefined : Number(nullCount)
