/**
 * Clamp a row range to the rows of a file.
 * Returns undefined when no rows are left in the range.
 *
 * @param {number} rowStart first row of the range
 * @param {number | undefined} rowEnd end of the range (exclusive), defaults to the end of the file
 * @param {number} numRows number of rows in the file
 * @returns {[number, number] | undefined}
 */
export function clampRowRange(rowStart, rowEnd, numRows) {
  const end = Math.min(rowEnd ?? numRows, numRows)
  if (rowStart >= end) return undefined
  return [rowStart, end]
}

/**
 * Split a row range into the pieces that fall inside each row group.
 * Row groups that do not overlap the range are left out.
 *
 * @param {FileMetaData} metadata
 * @param {number} rowStart first row of the range
 * @param {number} rowEnd end of the range (exclusive)
 * @returns {{ group: number, start: number, end: number, whole: boolean }[]}
 *   one span per overlapping row group, with the row group index, the rows of
 *   the range inside it, and whether the range holds every row of the group
 */
export function rowGroupSpans(metadata, rowStart, rowEnd) {
  /** @type {{ group: number, start: number, end: number, whole: boolean }[]} */
  const spans = []
  let groupStart = 0
  for (let group = 0; group < metadata.row_groups.length; group++) {
    const groupEnd = groupStart + Number(metadata.row_groups[group].num_rows)
    if (groupStart >= rowEnd) break
    if (groupEnd > rowStart) {
      spans.push({
        group,
        start: Math.max(rowStart, groupStart),
        end: Math.min(rowEnd, groupEnd),
        whole: coversGroup(rowStart, rowEnd, groupStart, groupEnd),
      })
    }
    groupStart = groupEnd
  }
  return spans
}

/**
 * Split a row range into the [start, end) pieces that fall inside each row group.
 *
 * @param {FileMetaData} metadata
 * @param {number} rowStart first row of the range
 * @param {number} rowEnd end of the range (exclusive)
 * @returns {[number, number][]} one range per overlapping row group
 */
export function rowGroupSlices(metadata, rowStart, rowEnd) {
  /** @type {[number, number][]} */
  const slices = []
  for (const { start, end } of rowGroupSpans(metadata, rowStart, rowEnd)) slices.push([start, end])
  return slices
}

/**
 * Whether the range [rowStart, rowEnd) holds every row of the group [groupStart, groupEnd).
 *
 * @param {number} rowStart
 * @param {number} rowEnd
 * @param {number} groupStart
 * @param {number} groupEnd
 * @returns {boolean}
 */
function coversGroup(rowStart, rowEnd, groupStart, groupEnd) {
  return rowStart <= groupStart && rowEnd >= groupEnd
}
